import { postAuthenticated } from './serverApi';

export interface MentorChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

interface MentorChatProfile {
  username?: string;
  level?: number;
}

/**
 * Where an answer came from.
 *
 * `ai` — generated by Gemini.
 * `offline` — retrieved from the local knowledge base, because no API key is
 *             configured or the model call failed.
 *
 * The interface shows this to the reader; a retrieved answer is never
 * presented as if a model wrote it.
 */
export type MentorSource = 'ai' | 'offline';

export interface MentorReply {
  text: string;
  source: MentorSource;
  /** Lesson the answer points at, when the knowledge base found one. */
  lessonId?: string;
}

export interface DailyChallenge {
  title: string;
  description: string;
  initialCode: string;
  testCases: { inputValues: string[]; expectedOutput: string; description: string }[];
  reward: { xp: number; coins: number };
  /** Present and 'fallback' when the server served a canned challenge. */
  source?: 'ai' | 'fallback';
}

const normalizeReply = (data: { text?: unknown; source?: unknown; lessonId?: unknown }): MentorReply => ({
  text: typeof data.text === 'string' && data.text.trim().length > 0
    ? data.text
    : 'Ответ пришёл пустым. Попробуйте переформулировать вопрос.',
  source: data.source === 'ai' ? 'ai' : 'offline',
  lessonId: typeof data.lessonId === 'string' ? data.lessonId : undefined,
});

/**
 * Asks for a hint about the current challenge.
 *
 * `challenge` must be a plain string — the server validates it with a string
 * reader and answers 400 for anything else. An earlier caller passed an object
 * here, which made the "analyse my code" action fail every single time.
 */
export const getMentorHint = async (
  code: string,
  challenge: string,
  error?: string,
): Promise<MentorReply> => {
  const data = await postAuthenticated<{ text: string; source?: string; lessonId?: string }>(
    '/mentor/hint',
    { code, challenge, error },
  );
  return normalizeReply(data);
};

export const getMentorChat = async (
  messages: MentorChatMessage[],
  profile?: MentorChatProfile,
): Promise<MentorReply> => {
  const data = await postAuthenticated<{ text: string; source?: string; lessonId?: string }>(
    '/mentor/chat',
    { messages: messages.slice(-6), profile },
  );
  return normalizeReply(data);
};

/**
 * Asks the knowledge base without an account.
 *
 * Used for signed-out visitors: it never reaches Gemini, so there is no cost
 * and nothing to authorise. Signed-in visitors go through `getMentorChat`,
 * which can use the model when one is configured.
 */
export const askMentorAnonymously = async (question: string): Promise<MentorReply> => {
  const response = await fetch('/api/mentor/ask', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ question }),
  });

  if (!response.ok) {
    throw new Error(`Mentor request failed: ${response.status}`);
  }

  return normalizeReply(await response.json());
};

export const generateDailyChallenge = async (userLevel: number): Promise<DailyChallenge> => {
  try {
    return await postAuthenticated<DailyChallenge>('/daily-challenge', { userLevel });
  } catch (requestError) {
    // The server already falls back on its own; this covers a network failure
    // before the request ever lands.
    console.error('Daily challenge request failed:', requestError);
    return {
      title: 'Среднее арифметическое',
      description:
        'Напишите функцию, которая принимает строку чисел через запятую и возвращает их среднее ' +
        'арифметическое, округлённое до целого.',
      initialCode: 'def calculate_average(numbers_str):\n    # Ваш код здесь\n    pass\n',
      testCases: [
        { inputValues: ['10,20,30,40'], expectedOutput: '25', description: 'Четыре числа' },
        { inputValues: ['5,5,5'], expectedOutput: '5', description: 'Одинаковые числа' },
      ],
      reward: { xp: 200, coins: 100 },
      source: 'fallback',
    };
  }
};
